<?php
namespace App\Http\Controllers;
use App\Models\{Product,Purchase,Supplier};use App\Services\InventoryTransactionService;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class PurchaseController extends Controller {
 public function index(Request $r){$filters=$r->validate(['search'=>['nullable','string','max:40'],'status'=>['nullable','in:completed,cancelled'],'from'=>['nullable','date'],'to'=>['nullable','date']]);if(!empty($filters['from'])&&!empty($filters['to'])&&$filters['to']<$filters['from'])throw \Illuminate\Validation\ValidationException::withMessages(['to'=>'Tanggal akhir harus sama atau setelah tanggal awal.']);$q=Purchase::with(['supplier','user'])->withCount('items')->when(!$r->user()->isAdmin(),fn($q)=>$q->where('user_id',$r->user()->id))->when($r->filled('search'),fn($q)=>$q->where('purchase_number','like','%'.$r->query('search').'%'))->when($r->filled('status'),fn($q)=>$q->where('status',$r->query('status')))->when($r->filled('from'),fn($q)=>$q->whereDate('purchased_at','>=',$r->query('from')))->when($r->filled('to'),fn($q)=>$q->whereDate('purchased_at','<=',$r->query('to')))->latest('purchased_at');$purchases=$q->paginate(15)->withQueryString();return view('purchases.index',compact('purchases'));}
 public function create(){return view('purchases.create',['products'=>Product::orderBy('name')->get(),'suppliers'=>Supplier::orderBy('name')->get()]);}
 public function store(Request $r,InventoryTransactionService $service){$items=collect($r->input('items',[]))->filter(fn($item)=>filled($item['product_id']??null)||filled($item['quantity']??null)||filled($item['unit_cost']??null))->values()->all();$r->merge(['items'=>$items]);$data=$r->validate(['supplier_id'=>['required','exists:suppliers,id'],'items'=>['required','array','min:1','max:10'],'items.*.product_id'=>['required','integer','distinct','exists:products,id'],'items.*.quantity'=>['required','integer','min:1','max:100000'],'items.*.unit_cost'=>['required','numeric','min:0','max:9999999999.99','decimal:0,2']]);$purchase=$service->purchase($data,$r->user()->id);return redirect()->route('purchases.show',$purchase)->with('success','Pembelian tersimpan dan stok berhasil ditambahkan.');}
 public function show(Request $r,Purchase $purchase){abort_unless($r->user()->isAdmin()||$purchase->user_id===$r->user()->id,403);$purchase->load(['supplier','user','items.product']);return view('purchases.show',compact('purchase'));}
 public function cancel(Purchase $purchase,InventoryTransactionService $service){abort_unless(auth()->user()->isAdmin(),403);$service->cancelPurchase($purchase);return back()->with('success','Pembelian dibatalkan dan stok disesuaikan.');}
}
